var s=[{title:`Partes de la barra`,text:`Una instalación típica tiene una barra, discos que encajan en ella y collarines para mantener los discos en su sitio cuando haga falta. La barra vacía puede resultar pesada para quien empieza, y las barras especiales tienen pesos y tamaños distintos. Anota el peso total que levantas, barra incluida, y no solo los discos.`},{title:`Por qué usar una barra`,text:`Los discos pequeños permiten añadir carga en pasos precisos, y una sola barra puede entrenar varios patrones de movimiento principales. Sin embargo, ambas manos sujetan una barra conectada, y eso no le conviene a todos los hombros o muñecas. Las mancuernas, las máquinas o los ejercicios con el peso corporal pueden ser mejor opción cuando tu equipamiento, tu comodidad o tu experiencia son limitados.`},{title:`Rack y seguridad`,text:`Para las sentadillas, coloca los ganchos en J a la altura adecuada para ti, y pon los brazos de seguridad o los pasadores donde cojan una repetición fallida sin dejar de permitirte recorrer todo el rango planeado. Para el press de banca, usa un ayudante competente o seguros bien colocados. Practica cómo entrar y salir del rack con la barra vacía antes de levantar cargas duras.`},{title:`Aprende antes de cargar`,text:`Practica la sentadilla, la bisagra, el press o el remo con una resistencia ligera hasta que la barra siga la misma trayectoria en cada repetición. Asegura los discos cuando haga falta, comprueba el espacio a tu alrededor y nunca des por hecho que un banco, un soporte o un rack improvisado pueden sostener una barra que cae. No necesitas probar tu máximo de una repetición para ganar fuerza si empiezas. Haz levantamientos con barra solo cuando tengas la barra y los discos adecuados, un rack u otra instalación segura y espacio suficiente. Si entrenas solo sin los seguros adecuados, o tienes límites para cargar la columna, elige otro ejercicio.`}];var o=[{label:`NSCA: seguridad y fundamentos del entrenamiento de fuerza`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: técnica del entrenamiento con pesas (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:s,sources:o};export{r as default,s as sections,o as sources};